#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Copies text to the clipboard where possible, so secrets and SQL needn't be
# printed. Returns failure if no clipboard tool is available.
to_clipboard() {
  if   command -v clip.exe >/dev/null 2>&1; then clip.exe
  elif command -v pbcopy   >/dev/null 2>&1; then pbcopy
  elif command -v wl-copy  >/dev/null 2>&1; then wl-copy
  elif command -v xclip    >/dev/null 2>&1; then xclip -selection clipboard
  else cat >/dev/null; return 1; fi
}

run_wizard() {

cd "$(dirname "$0")/.."
ENV_FILE=".env.local"
MIGRATION="supabase/migrations/20261122000000_settings.sql"

TOTAL_STAGES=6

banner "Munus Vitae: Supabase, Google sign-in and Vercel"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Supabase: create the project"
say "Supabase hosts the database and handles Google sign-in."
open_url "https://supabase.com/dashboard/projects"
step "Sign in (GitHub is easiest), then click 'New project'."
step "Name: munus-vitae. Generate a database password and keep it in a password manager (the app doesn't need it)."
step "Pick the region nearest you, then 'Create new project'. Wait until it shows as ready (~1-2 min)."
step "Click 'Connect' at the top (or Project Settings → Data API) and copy the Project URL."
note "It looks like https://abcdefghijklmnop.supabase.co"
while :; do
  ask VITE_SUPABASE_URL "Paste the Project URL:"
  VITE_SUPABASE_URL="${VITE_SUPABASE_URL%/}"
  [[ "$VITE_SUPABASE_URL" =~ ^https://[a-z0-9]+\.supabase\.co$ ]] && break
  warn "That doesn't look like https://<project-id>.supabase.co. Try again."
done
SUPABASE_REF="${VITE_SUPABASE_URL#https://}"; SUPABASE_REF="${SUPABASE_REF%%.*}"
step "Now Project Settings → API Keys. Copy the Publishable key (starts sb_publishable_)."
note "Older projects: Project Settings → API → 'anon public' key works too. Never use a secret/service_role key here."
while :; do
  ask VITE_SUPABASE_PUBLISHABLE_KEY "Paste the publishable key:"
  [[ "$VITE_SUPABASE_PUBLISHABLE_KEY" == sb_secret_* ]] && { warn "That's a secret key. Use the publishable one."; continue; }
  [[ -n "$VITE_SUPABASE_PUBLISHABLE_KEY" ]] && break
done
write_env VITE_SUPABASE_URL "$VITE_SUPABASE_URL"
write_env VITE_SUPABASE_PUBLISHABLE_KEY "$VITE_SUPABASE_PUBLISHABLE_KEY"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
CALLBACK_URL="$VITE_SUPABASE_URL/auth/v1/callback"
stage "Google: create the OAuth client"
say "Google needs to know Munus Vitae is allowed to sign you in."
open_url "https://console.cloud.google.com/auth/overview"
step "Pick (or create) a Google Cloud project, e.g. 'Munus Vitae'."
step "If asked to 'Get started': App name 'Munus Vitae', your email as support + contact email, Audience 'External', then Create."
step "Audience → Test users → add your own Google account (needed while the app is in 'Testing')."
step "Clients → 'Create client' → Application type 'Web application', name 'Munus Vitae'."
step "Under 'Authorized redirect URIs' add exactly:"
printf '\n      %s%s%s\n\n' "$BOLD" "$CALLBACK_URL" "$RESET"
step "Create. Google shows the Client ID and Client secret. Keep that dialog open."
note "Older console layout: APIs & Services → Credentials → Create credentials → OAuth client ID."
ask GOOGLE_CLIENT_ID "Paste the Client ID:"
ask_secret GOOGLE_CLIENT_SECRET "Paste the Client secret (hidden):"
note "These aren't saved anywhere; the next stage puts them into Supabase."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: turn on Google sign-in"
open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/auth/providers"
step "Authentication → Sign In / Providers → Google → enable it."
step "Client IDs:"
printf '\n      %s%s%s\n\n' "$BOLD" "$GOOGLE_CLIENT_ID" "$RESET"
if printf '%s' "$GOOGLE_CLIENT_SECRET" | to_clipboard; then
  step "Client Secret: it's on your clipboard now, so just paste it."
else
  warn "No clipboard tool found. Paste the secret from the Google dialog."
fi
step "Check the 'Callback URL' Supabase shows matches: $CALLBACK_URL"
step "Save."
unset GOOGLE_CLIENT_SECRET
pause "Saved? Press Enter"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase: create the settings table"
say "This runs $MIGRATION: the settings table, readable only by its owner."
open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/sql/new"
if confirm "Create the settings table in this Supabase project now?"; then
  if to_clipboard < "$MIGRATION"; then
    step "The SQL is on your clipboard. Paste it into the SQL editor and click Run."
  else
    warn "No clipboard tool found. Open $MIGRATION, copy all of it, paste into the editor and click Run."
  fi
  step "Expect 'Success. No rows returned'. ('relation \"settings\" already exists' means it was done before. That's fine.)"
  pause "Ran it? Press Enter"
else
  SKIPPED+=("Run $MIGRATION in the Supabase SQL editor")
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Vercel: deploy"
open_url "https://vercel.com/new"
step "Sign in with GitHub, then import the repository dnb14/munus-vitae."
note "Not listed? Click 'Adjust GitHub App Permissions' and give Vercel access to it."
step "Framework Preset should say Vite (leave build settings as they are)."
step "Open 'Environment Variables' and add these two:"
printf '\n      %sVITE_SUPABASE_URL%s              %s\n' "$BOLD" "$RESET" "$VITE_SUPABASE_URL"
printf '      %sVITE_SUPABASE_PUBLISHABLE_KEY%s  %s\n\n' "$BOLD" "$RESET" "$VITE_SUPABASE_PUBLISHABLE_KEY"
step "Click Deploy and wait for it to finish."
step "On the project page, copy the production domain (e.g. https://munus-vitae.vercel.app)."
while :; do
  ask VERCEL_URL "Paste the production URL:"
  VERCEL_URL="${VERCEL_URL%/}"
  [[ "$VERCEL_URL" =~ ^https?:// ]] || VERCEL_URL="https://$VERCEL_URL"
  [[ "$VERCEL_URL" =~ ^https://[^/[:space:]]+$ ]] && break
  warn "Expected something like https://munus-vitae.vercel.app"
done

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Supabase: allowed redirect URLs"
say "After Google sign-in, Supabase only sends you back to URLs on this list."
open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/auth/url-configuration"
step "Site URL:"
printf '\n      %s%s%s\n\n' "$BOLD" "$VERCEL_URL" "$RESET"
step "Redirect URLs → Add URL, once for each:"
printf '\n      %s%s%s\n      %shttp://localhost:5173%s\n\n' "$BOLD" "$VERCEL_URL" "$RESET" "$BOLD" "$RESET"
step "Save."
pause "Saved? Press Enter"

say ""
say "Last check, by hand:"
step "Open $VERCEL_URL → Sign in with Google → you see the page."
step "Reload: still signed in. Sign out: back to the sign-in screen."
step "Locally: npm run dev → http://localhost:5173 → same checks."
pause

finish
}

run_wizard "$@"; exit
